mapper.select:
select ds.*
from DATA_SOURCE ds

    and (#{admin} = true
    or ds.USER_ID = #{userId}
    or exists(
    select 1 from PROJECT_ACCESS pa where pa.ACCESS_OBJECT_TYPE = 'USER'
    and pa.ACCESS_OBJECT_ID = #{userId}
    and pa.PROJECT_ID = ds.PROJECT_ID
    and (
        not exists (
            select 1 from PROJECT_ACCESS_ENVIRONMENT pae0
            where pae0.PROJECT_ACCESS_ID = pa.ID
        )
        or exists (
            select 1 from PROJECT_ACCESS_ENVIRONMENT pae
            where pae.PROJECT_ACCESS_ID = pa.ID
              and pae.ENVIRONMENT_ID = ds.ENVIRONMENT_ID
        )
    )
    )
    or exists (
    select 1
    from PROJECT_ACCESS pa
    LEFT JOIN TEAM_USER tu on tu.TEAM_ID = pa.ACCESS_OBJECT_ID and pa.ACCESS_OBJECT_TYPE = 'TEAM'
    left join TEAM t on t.id = tu.TEAM_ID
    where tu.USER_ID = #{userId}
    and pa.PROJECT_ID = ds.PROJECT_ID
    and t.STATUS = 'VALID'
    and (
        not exists (
            select 1 from PROJECT_ACCESS_ENVIRONMENT pae0
            where pae0.PROJECT_ACCESS_ID = pa.ID
        )
        or exists (
            select 1 from PROJECT_ACCESS_ENVIRONMENT pae
            where pae.PROJECT_ACCESS_ID = pa.ID
              and pae.ENVIRONMENT_ID = ds.ENVIRONMENT_ID
        )
    )
    )
    )

        and (ds.alias like concat('%',#{searchKey},'%') or ds.url like concat('%',#{searchKey},'%'))


        ${orderBy}
